-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.path_event_discordance_v1
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.path_event_discordance_v1 AS WITH row_base AS (SELECT research_id, surgery_episode_uid, path_surgery_id, tumor_ordinal, synoptic_row_ix, specimen_id, primary_histology, laterality, site, size_greatest_dimension_cm, extrathyroidal_extension, gross_ete, t_stage_ajcc8 AS reported_t_stage_ajcc8, t_stage_ajcc7 AS reported_t_stage_ajcc7 FROM manuscript_workspace.canonical_path_malignant_events_v1_keyed), row_hist AS (SELECT b.*, CASE  WHEN (((lower(main."trim"(COALESCE(primary_histology, ''))) IN ('mtc', 'medullary')) OR (lower(primary_histology) ~~ '%medullary%'))) THEN ('MTC') WHEN (((lower(primary_histology) ~~ '%anaplastic%') OR (lower(primary_histology) ~~ '%sarcomatoid%'))) THEN ('ATC') WHEN ((lower(primary_histology) ~~ '%niftp%')) THEN ('non_staged') WHEN (((lower(primary_histology) ~~ '%ftump%') OR (lower(primary_histology) ~~ '%uncertain malignant potential%'))) THEN ('non_staged') WHEN (((lower(primary_histology) ~~ '%follicular adenoma%') OR (lower(primary_histology) ~~ '%atypical follicular adenoma%') OR (lower(primary_histology) ~~ '%atypical hurthle cell neoplasm%') OR (lower(primary_histology) ~~ '%hurthle cell adenoma%'))) THEN ('non_staged') WHEN (((lower(primary_histology) ~~ '%ptc%') OR (lower(primary_histology) ~~ '%papillary%') OR (lower(primary_histology) ~~ '%follicular car%') OR (lower(primary_histology) ~~ '%follicular caric%') OR (lower(primary_histology) ~~ '%hurthle%') OR (lower(primary_histology) ~~ '%hürthle%') OR (lower(primary_histology) ~~ '%oncocytic%') OR (lower(primary_histology) ~~ '%poorly differentiated%') OR (lower(primary_histology) ~~ '%pdtc%') OR (lower(primary_histology) ~~ '%differentiated high grade%') OR (lower(primary_histology) ~~ '%dhgtc%') OR (lower(primary_histology) ~~ '%differentiated thyroid%'))) THEN ('DTC') WHEN (((primary_histology IS NULL) OR (main."trim"(primary_histology) = ''))) THEN ('unknown_histology') ELSE 'other' END AS histology_bucket FROM row_base AS b), row_ete AS (SELECT rh.*, CASE  WHEN (((extrathyroidal_extension IS NULL) OR (main."trim"(extrathyroidal_extension) = ''))) THEN ('unknown') WHEN ((lower(main."trim"(extrathyroidal_extension)) IN ('x', '`x', 'false', 'no', 'n/a', 'none', 'absent'))) THEN ('absent') WHEN ((lower(extrathyroidal_extension) ~~ '%indetermin%')) THEN ('unknown') WHEN (((lower(extrathyroidal_extension) ~~ '%present%') OR (lower(extrathyroidal_extension) ~~ '%minimal%') OR (lower(extrathyroidal_extension) ~~ '%microscop%') OR (lower(extrathyroidal_extension) ~~ '%focal%') OR (lower(extrathyroidal_extension) ~~ '%extensi%') OR (lower(extrathyroidal_extension) ~~ '%extesive%') OR (lower(extrathyroidal_extension) ~~ 'yes%') OR (lower(extrathyroidal_extension) ~~ '%true%') OR (lower(extrathyroidal_extension) ~~ '%extension%') OR (lower(extrathyroidal_extension) ~~ '%perithyroidal%'))) THEN ('present') ELSE 'other' END AS ete_norm FROM row_hist AS rh), row_ete_effective AS (SELECT re.*, CASE  WHEN ((gross_ete = 1)) THEN (CAST('t' AS BOOLEAN)) WHEN ((ete_norm = 'present')) THEN (CAST('t' AS BOOLEAN)) WHEN ((ete_norm = 'absent')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END AS gross_ete_effective FROM row_ete AS re), row_derived AS (SELECT ref.*, CASE  WHEN ((histology_bucket = 'non_staged')) THEN ('not_applicable') WHEN ((histology_bucket = 'other')) THEN ('unknown_histology_staging') WHEN ((histology_bucket = 'unknown_histology')) THEN (NULL) WHEN ((CAST(gross_ete_effective AS BOOLEAN) IS NOT DISTINCT FROM CAST('t' AS BOOLEAN))) THEN ('indeterminate_t3b_t4a_t4b_requires_llm') WHEN (((CAST(gross_ete_effective AS BOOLEAN) IS NOT DISTINCT FROM CAST('f' AS BOOLEAN)) AND (size_greatest_dimension_cm IS NOT NULL) AND (size_greatest_dimension_cm <= 1.0))) THEN ('T1a') WHEN (((CAST(gross_ete_effective AS BOOLEAN) IS NOT DISTINCT FROM CAST('f' AS BOOLEAN)) AND (size_greatest_dimension_cm > 1.0) AND (size_greatest_dimension_cm <= 2.0))) THEN ('T1b') WHEN (((CAST(gross_ete_effective AS BOOLEAN) IS NOT DISTINCT FROM CAST('f' AS BOOLEAN)) AND (size_greatest_dimension_cm > 2.0) AND (size_greatest_dimension_cm <= 4.0))) THEN ('T2') WHEN (((CAST(gross_ete_effective AS BOOLEAN) IS NOT DISTINCT FROM CAST('f' AS BOOLEAN)) AND (size_greatest_dimension_cm > 4.0))) THEN ('T3a') WHEN (((gross_ete_effective IS NULL) AND (size_greatest_dimension_cm IS NOT NULL) AND (size_greatest_dimension_cm <= 1.0))) THEN ('T1a_assumes_no_ete') WHEN (((gross_ete_effective IS NULL) AND (size_greatest_dimension_cm IS NOT NULL) AND (size_greatest_dimension_cm > 1.0) AND (size_greatest_dimension_cm <= 2.0))) THEN ('T1b_assumes_no_ete') WHEN (((gross_ete_effective IS NULL) AND (size_greatest_dimension_cm IS NOT NULL) AND (size_greatest_dimension_cm > 2.0) AND (size_greatest_dimension_cm <= 4.0))) THEN ('T2_assumes_no_ete') WHEN (((gross_ete_effective IS NULL) AND (size_greatest_dimension_cm IS NOT NULL) AND (size_greatest_dimension_cm > 4.0))) THEN ('T3a_assumes_no_ete') ELSE NULL END AS derived_t_stage_ajcc8 FROM row_ete_effective AS "ref"), row_lat AS (SELECT rd.*, CASE  WHEN (((laterality IS NULL) OR (main."trim"(laterality) = ''))) THEN (NULL) WHEN ((lower(main."trim"(laterality)) = 'bilateral')) THEN ('bilateral') WHEN (((lower(laterality) ~~ '%left%') AND (lower(laterality) ~~ '%right%'))) THEN ('bilateral') WHEN ((lower(laterality) ~~ '%left%')) THEN ('left') WHEN ((lower(laterality) ~~ '%right%')) THEN ('right') WHEN ((lower(laterality) ~~ '%isthmus%')) THEN ('isthmus') ELSE 'other' END AS lat_norm, CASE  WHEN (((site IS NULL) OR (main."trim"(site) = ''))) THEN (NULL) WHEN (((lower(site) ~~ '%left%') AND (lower(site) ~~ '%right%'))) THEN ('bilateral') WHEN ((lower(site) ~~ '%left%')) THEN ('left') WHEN ((lower(site) ~~ '%right%')) THEN ('right') WHEN ((lower(site) ~~ '%isthmus%')) THEN ('isthmus') ELSE 'other' END AS site_norm FROM row_derived AS rd)SELECT research_id, surgery_episode_uid, path_surgery_id, tumor_ordinal, synoptic_row_ix, specimen_id, primary_histology, histology_bucket, size_greatest_dimension_cm, extrathyroidal_extension AS ete_raw, ete_norm, gross_ete AS gross_ete_raw_flag, gross_ete_effective, laterality AS laterality_raw, lat_norm, site AS site_raw, site_norm, reported_t_stage_ajcc7, reported_t_stage_ajcc8, derived_t_stage_ajcc8, CASE  WHEN (((reported_t_stage_ajcc8 IS NULL) OR (derived_t_stage_ajcc8 IS NULL))) THEN (NULL) WHEN ((derived_t_stage_ajcc8 IN ('not_applicable', 'unknown_histology_staging', 'indeterminate_t3b_t4a_t4b_requires_llm', 'T1a_assumes_no_ete', 'T1b_assumes_no_ete', 'T2_assumes_no_ete', 'T3a_assumes_no_ete'))) THEN (NULL) WHEN ((derived_t_stage_ajcc8 = reported_t_stage_ajcc8)) THEN (CAST('f' AS BOOLEAN)) ELSE CAST('t' AS BOOLEAN) END AS discordance_t_stage_flag, CASE  WHEN ((reported_t_stage_ajcc8 IS NULL)) THEN ('reported_t_stage_ajcc8_missing') WHEN ((derived_t_stage_ajcc8 IS NULL)) THEN ('size_and_ete_both_missing') WHEN ((derived_t_stage_ajcc8 = 'not_applicable')) THEN ('histology_not_staged') WHEN ((derived_t_stage_ajcc8 = 'unknown_histology_staging')) THEN ('unknown_histology_bucket') WHEN ((derived_t_stage_ajcc8 = 'indeterminate_t3b_t4a_t4b_requires_llm')) THEN ('gross_ete_present_t4b_requires_llm') WHEN ((derived_t_stage_ajcc8 ~~ '%_assumes_no_ete')) THEN ('ete_unknown_derived_with_assumption') WHEN ((derived_t_stage_ajcc8 = reported_t_stage_ajcc8)) THEN ('concordant') ELSE 'reported_neq_derived' END AS t_stage_derivation_note, CASE  WHEN (((lat_norm IS NULL) OR (lat_norm = 'bilateral') OR (lat_norm = 'isthmus') OR (lat_norm = 'other'))) THEN (NULL) WHEN (((site_norm IS NULL) OR (site_norm IN ('isthmus', 'other')))) THEN (NULL) WHEN (((lat_norm = 'left') AND (site_norm = 'right'))) THEN (CAST('t' AS BOOLEAN)) WHEN (((lat_norm = 'right') AND (site_norm = 'left'))) THEN (CAST('t' AS BOOLEAN)) WHEN (((lat_norm = 'left') AND (site_norm = 'bilateral'))) THEN (CAST('t' AS BOOLEAN)) WHEN (((lat_norm = 'right') AND (site_norm = 'bilateral'))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS discordance_laterality_flag FROM row_lat;
